with remaining_keys as (select supplier_id, category from products except all select supplier_id, category from products where stock_qty = 249), kept_rows as (select s.* from products s inner join remaining_keys k on s.supplier_id = k.supplier_id and s.category = k.category) select product_name, brand, price, stock_qty, launch_date, tags, supplier_id from kept_rows order by brand desc nulls first;
